/* R-18 分级提示：一天只弹一次（按本机日期，过零点自动重置），当天弹过就直接跑 */
function pgToday() {
  const d = new Date()
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`
}
function pgGateSeenToday() {
  try { return localStorage.getItem('pixiv-gallery.r18gate') === pgToday() } catch { return false }
}
function pgMarkGateSeen() {
  try { localStorage.setItem('pixiv-gallery.r18gate', pgToday()) } catch { /* 存不下就每次问一遍 */ }
}
function pgAddSoftRefresh(fn) {
  const cur = Array.isArray(window.__pgSoftRefresh)
    ? window.__pgSoftRefresh
    : (typeof window.__pgSoftRefresh === 'function' ? [window.__pgSoftRefresh] : [])
  cur.push(fn)
  window.__pgSoftRefresh = cur
  return () => {
    const now = Array.isArray(window.__pgSoftRefresh) ? window.__pgSoftRefresh : []
    const i = now.indexOf(fn)
    if (i >= 0) now.splice(i, 1)
    if (!now.length) { try { delete window.__pgSoftRefresh } catch { /* ignore */ } }
  }
}

const PERFECT_COLLECTION = '藏赏两宜，无可挑剔'
const glowOf = (s) => {
  const n = Number(s)
  if (!Number.isFinite(n)) return 'rgba(148,163,184,.5)'
  if (n >= 10) return 'rgba(250,204,21,.8)'
  if (n >= 9) return 'rgba(244,114,182,.72)'
  if (n >= 8) return 'rgba(56,189,248,.72)'
  if (n >= 6) return 'rgba(52,211,153,.66)'
  return 'rgba(148,163,184,.5)'
}
/* 按可视区域算一页能放几件：取网格实际列宽/行高，窗口一变就重算。
   主人要的是「每页被作品填满」，不再用固定的 15 / 20 / 30。 */
const pgAutoFitCount = (gridSel, cardSel, gap, reserve, minRows, minCount, maxCount) => {
  try {
    const grid = document.querySelector(gridSel)
    if (!grid) return 0
    const card = grid.querySelector(cardSel)
    if (!card) return 0
    const gw = grid.clientWidth || 0
    const cr = card.getBoundingClientRect()
    if (!gw || !cr.width || !cr.height) return 0
    const top = Math.max(0, grid.getBoundingClientRect().top)
    const avail = Math.max(cr.height, window.innerHeight - top - reserve)
    const cols = Math.max(1, Math.round((gw + gap) / (cr.width + gap)))
    const rows = Math.max(minRows || 2, Math.floor((avail + gap) / (cr.height + gap)))
    const fit = Math.max(cols, cols * rows)
    const lo = Math.max(1, Math.trunc(Number(minCount) || 1))
    const hi = Math.max(lo, Math.trunc(Number(maxCount) || 999))
    return Math.max(lo, Math.min(hi, fit))
  } catch { return 0 }
}
const pgPageBounds = (kind) => {
  const grid = document.querySelector(kind === 'library' ? '[data-pg-lib-grid]' : '[data-pg-grid]')
  const w = Number(grid && grid.clientWidth) || Number(window.innerWidth) || 1280
  if (kind === 'library') return w >= 980 ? [36, 200] : w >= 780 ? [24, 200] : w >= 620 ? [12, 80] : [8, 48]
  return w >= 980 ? [16, 16] : w >= 760 ? [8, 16] : [4, 16]
}
